// hermes minimal htmx-compatible shim.
//
// This file ships an opinionated subset of htmx 2.x just large enough to
// drive the operator console: `hx-get`, `hx-post`, `hx-target`, `hx-swap`
// (innerHTML / outerHTML / delete), `hx-trigger`, `hx-confirm`,
// `hx-push-url`, `hx-headers`, and `hx-swap-oob`.  Replace with the
// official htmx.min.js (https://htmx.org) for full feature compatibility
// — the templates were authored against the standard attribute set so a
// drop-in replacement Just Works.
(function () {
  "use strict";

  function $(sel, root) { return (root || document).querySelector(sel); }
  function $$(sel, root) { return Array.from((root || document).querySelectorAll(sel)); }

  // makeFragment parses html in a parsing context that matches where the
  // result will live in the DOM.  Without this, "<tr>...</tr>" set on a
  // <div>'s innerHTML is silently stripped (the HTML parser only keeps
  // <tr> children of <table>/<tbody>/<thead>/<tfoot>, and <td> only
  // inside <tr>).  Pick the right holder based on the swap target.
  function makeFragment(html, target, mode) {
    var ctx = mode === "outerHTML" ? (target && target.parentNode) : target;
    var ctxTag = ctx && ctx.tagName;
    var holder;
    if (ctxTag === "TABLE") {
      // outerHTML on a <tbody> sits inside <table>; we need a <table>
      // holder so the parser keeps the <tbody>.
      holder = document.createElement("table");
    } else if (ctxTag === "TBODY" || ctxTag === "THEAD" || ctxTag === "TFOOT") {
      holder = document.createElement("tbody");
    } else if (ctxTag === "TR") {
      holder = document.createElement("tr");
    } else if (ctxTag === "SELECT" || ctxTag === "OPTGROUP") {
      holder = document.createElement("select");
    } else {
      holder = document.createElement("div");
    }
    holder.innerHTML = (html || "").trim();
    // <table> holder wraps content in <tbody> implicitly; unwrap so the
    // caller sees the real elements (e.g. a <tbody> swap target).
    if (holder.tagName === "TABLE" && holder.firstElementChild &&
        holder.firstElementChild.tagName === "TBODY" &&
        ctxTag === "TABLE") {
      // Unwrap the synthetic tbody if it only contains tbody children
      // (i.e. our payload is itself a <tbody>); browsers will create
      // an implicit tbody around row-only payloads, but here we want
      // the real tbody from the response.
      var only = holder.firstElementChild;
      if (only.children.length && only.children[0].tagName === "TBODY") {
        holder = only;
      }
    }
    return holder;
  }

  function resolveTarget(el) {
    var t = el.getAttribute("hx-target");
    if (!t) return el;
    if (t === "this") return el;
    if (t.startsWith("#") || t.startsWith(".")) return $(t);
    return $("#" + t) || $(t);
  }

  // cleanGroupSiblings removes every existing element matching the
  // group(s) the incoming row will own, so the partial-includes-children
  // shape (e.g. _tagset_row.html emitting the tag-set <tr> AND its
  // level-3 children) can swap cleanly without leaving orphan rows
  // behind in the same <tbody>.
  function cleanGroupSiblings(target, holder) {
    if (!target || !holder) return;
    // For every incoming top-level node that declares `data-tg-id`,
    // remove any current rows whose `data-group` matches.
    Array.prototype.forEach.call(holder.children || [], function (incoming) {
      var tg = incoming.getAttribute && incoming.getAttribute("data-tg-id");
      if (!tg) return;
      $$('[data-group="' + tg + '"]').forEach(function (n) { n.remove(); });
    });
  }

  function swapInto(target, html, mode) {
    if (!target) return;
    mode = mode || target.getAttribute("hx-swap") || "innerHTML";
    if (mode === "delete") {
      target.remove();
      return;
    }
    var holder = makeFragment(html, target, mode);
    if (mode === "outerHTML") {
      cleanGroupSiblings(target, holder);
      while (holder.firstChild) target.parentNode.insertBefore(holder.firstChild, target);
      target.remove();
    } else {
      target.innerHTML = "";
      while (holder.firstChild) target.appendChild(holder.firstChild);
    }
    bind(document);
  }

  // applyOOB scans an HTML response for elements carrying
  // `hx-swap-oob` and routes each one to its in-DOM target.  Accepts
  // both:
  //   <tr id="x" hx-swap-oob="true">…</tr>      (body context)
  //   <template><td hx-swap-oob="true" id="x">…</td></template>
  //                                              (table-fragment context)
  //
  // The <template> wrapper is required for OOB elements like <td>
  // and <tr> because the HTML parser drops them when set as plain
  // body innerHTML.  Returns the response HTML with OOB elements (and
  // their template wrappers) stripped so the caller's main swap does
  // not double-apply them.
  function collectOOB(root) {
    var out = [];
    Array.prototype.forEach.call(root.querySelectorAll("[hx-swap-oob]"), function (el) { out.push(el); });
    return out;
  }

  function applyOOB(html) {
    if (!html || html.indexOf("hx-swap-oob") === -1) return html;
    var doc = document.implementation.createHTMLDocument("");
    doc.body.innerHTML = html;

    var oobs = collectOOB(doc.body);
    Array.prototype.forEach.call(doc.body.querySelectorAll("template"), function (t) {
      collectOOB(t.content).forEach(function (el) { oobs.push(el); });
    });

    oobs.forEach(function (el) {
      var spec = el.getAttribute("hx-swap-oob") || "true";
      el.removeAttribute("hx-swap-oob");
      var mode = "outerHTML"; var sel = "";
      if (spec === "true") {
        sel = el.id ? "#" + el.id : "";
      } else {
        var i = spec.indexOf(":");
        if (i < 0) { mode = spec; sel = el.id ? "#" + el.id : ""; }
        else      { mode = spec.slice(0, i); sel = spec.slice(i + 1); }
      }
      if (!sel) return;
      var target = $(sel);
      if (!target) return;
      if (mode === "delete") {
        target.remove();
      } else if (mode === "innerHTML") {
        target.innerHTML = el.innerHTML;
      } else {
        var clone = document.importNode(el, true);
        target.replaceWith(clone);
      }
    });

    // Strip every <template> wrapper from the leftover HTML so the
    // caller's main swap only sees the primary content.
    Array.prototype.forEach.call(doc.body.querySelectorAll("template"), function (t) { t.remove(); });
    return doc.body.innerHTML;
  }

  function readForm(el) {
    var form = el.closest("form");
    if (!form) return new URLSearchParams();
    return new URLSearchParams(new FormData(form));
  }

  // rowContextHeaders extracts the indent (0/1/2) and parent group of
  // the closest <tr> ancestor so a server-side row swap renders with
  // the same nesting it had before.  Without these, every action swap
  // visually flattens the row to indent 0.
  function rowContextHeaders(el) {
    var row = el && el.closest && el.closest("tr");
    if (!row) return {};
    var indent = "0";
    if (row.classList.contains("tree-lvl-3")) indent = "2";
    else if (row.classList.contains("tree-lvl-2")) indent = "1";
    var headers = { "Hx-Indent": indent };
    var grp = row.getAttribute("data-group");
    if (grp) headers["Hx-Group"] = grp;
    return headers;
  }

  function dispatch(el, method) {
    var url = el.getAttribute("hx-" + method.toLowerCase());
    if (!url) return;
    var confirmMsg = el.getAttribute("hx-confirm");
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    var target = resolveTarget(el);
    var swap = el.getAttribute("hx-swap") || (target === el ? "outerHTML" : "innerHTML");
    var headers = {
      "Hx-Request": "true",
      "Hx-Current-URL": window.location.href
    };
    Object.assign(headers, rowContextHeaders(el));
    var explicit = el.getAttribute("hx-headers");
    if (explicit) {
      try { Object.assign(headers, JSON.parse(explicit)); } catch (e) { /* ignore */ }
    }
    if (target && target.id) headers["Hx-Target"] = target.id;
    var body = null;
    var fetchURL = url;
    if (method === "GET") {
      var params = readForm(el);
      if (Array.from(params).length) fetchURL += (url.indexOf("?") < 0 ? "?" : "&") + params.toString();
    } else {
      body = readForm(el);
    }
    fetch(fetchURL, { method: method, headers: headers, body: body, credentials: "same-origin" })
      .then(function (r) { return r.text().then(function (t) { return [r, t]; }); })
      .then(function (pair) {
        var resp = pair[0], text = pair[1];
        if (resp.ok || resp.status === 202) {
          // OOB elements first so the main swap does not see them.
          text = applyOOB(text);
          if (text.trim()) {
            swapInto(target, text, swap);
          }
          if (el.getAttribute("hx-push-url") === "true") {
            try { history.pushState({}, "", fetchURL); } catch (e) { /* ignore */ }
          }
        } else {
          console.warn("hx error", resp.status, text);
        }
      })
      .catch(function (e) { console.warn("hx fetch", e); });
  }

  function bind(root) {
    $$("[hx-get],[hx-post]", root).forEach(function (el) {
      if (el.__hxBound) return;
      el.__hxBound = true;
      var method = el.hasAttribute("hx-get") ? "GET" : "POST";
      var trig = (el.getAttribute("hx-trigger") || (el.tagName === "FORM" ? "submit" : "click")).split(",");
      trig.forEach(function (t) {
        t = t.trim();
        if (!t) return;
        el.addEventListener(t, function (ev) { ev.preventDefault(); dispatch(el, method); });
      });
    });
  }

  // ── SSE ──────────────────────────────────────────────────────────────
  // Event types whose state change is reflected on a visible row, so
  // the shim refetches the affected row and ancestors.  Action-driven
  // updates carry their changes inline via OOB swaps; SSE refreshes
  // are the cross-tab fallback.
  var rowRefreshEvents = {
    scan: 1, scan_error: 1, fetch: 1, fetch_error: 1,
    approve: 1, reject: 1, rescind: 1,
    validate_voided: 1, validate_adopted: 1
  };
  var repoRefreshEvents = {
    validate_denied: 1, validate_adopted: 1
  };

  function baseFromConnect(connectURL) {
    return (connectURL || "").replace(/\/events$/, "");
  }

  function refreshRow(base, id) {
    var row = document.getElementById("image-" + id);
    if (!row) return;
    var headers = {
      "Hx-Request": "true",
      "Hx-Current-URL": window.location.href
    };
    Object.assign(headers, rowContextHeaders(row.querySelector("button") || row));
    fetch(base + "/images/" + id + "/row", { headers: headers, credentials: "same-origin" })
      .then(function (r) {
        if (r.status === 410) { row.remove(); return null; }
        return r.ok ? r.text() : null;
      })
      .then(function (html) {
        if (!html) return;
        html = applyOOB(html);
        if (html.trim()) swapInto(row, html, "outerHTML");
      })
      .catch(function () {});
  }

  // refreshRepoTbody refetches the entire <tbody> for a repo.  Whole-
  // tbody swap means descendant rows (level-2 + level-3) come along
  // atomically — no orphan rows from a partial that includes children
  // but is targeted at a single <tr>.
  function refreshRepoTbody(rowID) {
    var tbody = document.getElementById("tbody-" + rowID);
    if (!tbody) return;
    var url = tbody.getAttribute("data-refresh");
    if (!url) return;
    fetch(url, { headers: { "Hx-Request": "true" }, credentials: "same-origin" })
      .then(function (r) { return r.ok ? r.text() : null; })
      .then(function (html) { if (html) swapInto(tbody, html, "outerHTML"); })
      .catch(function () {});
  }

  function refreshTagSetRow(rowID) {
    var row = document.getElementById("row-" + rowID);
    if (!row) return;
    var url = row.getAttribute("data-refresh");
    if (!url) return;
    fetch(url, { headers: { "Hx-Request": "true" }, credentials: "same-origin" })
      .then(function (r) { return r.ok ? r.text() : null; })
      .then(function (html) { if (html) swapInto(row, html, "outerHTML"); })
      .catch(function () {});
  }

  function refreshAncestors(start) {
    var seen = {};
    var groupId = start.getAttribute("data-group");
    while (groupId && !seen[groupId]) {
      seen[groupId] = 1;
      var parentRowID = groupId.replace(/^tg-/, "");
      if (parentRowID.indexOf("repo:") === 0) {
        refreshRepoTbody(parentRowID);
        break; // tbody refresh handles every child level
      }
      if (parentRowID.indexOf("ts:") === 0) {
        refreshTagSetRow(parentRowID);
      }
      var parent = document.getElementById("row-" + parentRowID);
      if (!parent) break;
      groupId = parent.getAttribute("data-group");
    }
  }

  function refreshDetail(base, id) {
    var section = document.getElementById("image-detail");
    if (!section) return;
    if (section.dataset.imageId !== String(id)) return;
    fetch(base + "/images/" + id + "/detail", {
      headers: { "Hx-Request": "true" }, credentials: "same-origin"
    })
      .then(function (r) { return r.ok ? r.text() : null; })
      .then(function (html) { if (html) swapInto(section, html, "innerHTML"); })
      .catch(function () {});
  }

  function refreshRepoFromEvent(data) {
    var details = data && data.details;
    if (!details) return;
    if (typeof details === "string") {
      try { details = JSON.parse(details); } catch (e) { return; }
    }
    var reg = details.registry, repo = details.repository || details.repo;
    if (!reg || !repo) return;
    refreshRepoTbody("repo:" + reg + "|" + repo);
  }

  function sseStart() {
    $$("[sse-connect]").forEach(function (root) {
      if (root.__sseSrc) return;
      var url = root.getAttribute("sse-connect");
      var base = baseFromConnect(url);
      var src = new EventSource(url);
      root.__sseSrc = src;
      src.addEventListener("event", function (ev) {
        var data = null;
        try { data = JSON.parse(ev.data); } catch (e) { /* ignore */ }
        if (data && data.image_id && rowRefreshEvents[data.event_type]) {
          var row = document.getElementById("image-" + data.image_id);
          if (row) refreshAncestors(row);
          refreshRow(base, data.image_id);
          refreshDetail(base, data.image_id);
        }
        if (data && repoRefreshEvents[data.event_type]) {
          refreshRepoFromEvent(data);
        }
        $$("[sse-swap]", root).forEach(function (slot) {
          var swap = slot.getAttribute("hx-swap") || "innerHTML";
          var html;
          if (data) {
            html = "<code>" + (data.event_type || "?") + "</code> " +
                   (data.image_id ? "image #" + data.image_id : "");
          } else {
            html = ev.data;
          }
          swapInto(slot, html, swap);
        });
      });
      src.onerror = function () { /* let the browser auto-reconnect */ };
    });
  }

  // ── tree expand/collapse ───────────────────────────────────────────────
  var treeKey = function (id) { return "hermes:tree:" + id; };

  function applyToggle(btn, expanded) {
    btn.setAttribute("aria-expanded", String(expanded));
    var label = btn.dataset.expandLabel || "expand";
    btn.textContent = expanded ? "collapse" : label;
    var target = btn.getAttribute("aria-controls") || "";
    target.split(" ").forEach(function (group) {
      $$('[data-group="' + group + '"]').forEach(function (row) {
        if (expanded) {
          row.removeAttribute("hidden");
        } else {
          row.setAttribute("hidden", "");
          $$("[data-row-id][aria-expanded='true']", row).forEach(function (inner) {
            applyToggle(inner, false);
            try { localStorage.setItem(treeKey(inner.dataset.rowId), "0"); } catch (_) {}
          });
        }
      });
    });
  }

  document.addEventListener("click", function (e) {
    var btn = e.target.closest("[data-row-id][aria-controls]");
    if (!btn) return;
    e.preventDefault();
    var open = btn.getAttribute("aria-expanded") !== "true";
    applyToggle(btn, open);
    try { localStorage.setItem(treeKey(btn.dataset.rowId), open ? "1" : "0"); } catch (_) {}
  });

  // ── clipboard ─────────────────────────────────────────────────────────
  document.addEventListener("click", function (e) {
    var btn = e.target.closest("[data-clipboard]");
    if (!btn) return;
    e.preventDefault();
    e.stopPropagation();
    var text = btn.getAttribute("data-clipboard") || "";
    var done = function () {
      btn.classList.add("copied");
      setTimeout(function () { btn.classList.remove("copied"); }, 1000);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, function () {});
    } else {
      var ta = document.createElement("textarea");
      ta.value = text;
      ta.setAttribute("readonly", "");
      ta.style.position = "absolute"; ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand("copy"); done(); } catch (_) {}
      document.body.removeChild(ta);
    }
  });

  function restoreTree() {
    $$("[data-row-id][aria-controls]").forEach(function (btn) {
      var v = null;
      try { v = localStorage.getItem(treeKey(btn.dataset.rowId)); } catch (_) {}
      if (v === "1") applyToggle(btn, true);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () { bind(document); sseStart(); restoreTree(); });
  } else {
    bind(document);
    sseStart();
    restoreTree();
  }
})();
